//! Cloud commands for managing Spice Cloud resources.

mod client;
mod config;

use crate::context::RuntimeContext;
use crate::error::{InvalidArgumentSnafu, Result};
use crate::output::TableOutput;
use clap::{Args, Subcommand};
use snafu::ResultExt;

pub use client::CloudClient;
pub use config::{CloudLink, get_linked_app, load_cloud_link, remove_cloud_link, save_cloud_link};

/// Arguments for the cloud command.
#[derive(Args, Debug)]
pub struct CloudArgs {
    #[command(subcommand)]
    pub command: CloudCommands,
}

/// Cloud subcommands.
#[derive(Subcommand, Debug)]
pub enum CloudCommands {
    /// Login to Spice Cloud
    Login(LoginArgs),

    /// Logout from Spice Cloud
    Logout,

    /// Show current authenticated user
    Whoami,

    /// Link current directory to a Spice Cloud app
    Link(LinkArgs),

    /// Unlink current directory from Spice Cloud app
    Unlink,

    /// List all apps
    Apps,

    /// List deployments for an app
    Deployments(DeploymentsArgs),

    /// List available regions
    Regions,

    /// List available container images
    Images(ImagesArgs),

    /// Manage secrets for an app
    #[command(subcommand)]
    Secrets(SecretsCommands),

    /// View deployment logs
    Logs(LogsArgs),

    /// Create a new resource
    #[command(subcommand)]
    Create(CreateCommands),

    /// Get details of a resource
    #[command(subcommand)]
    Get(GetCommands),

    /// Update a resource
    #[command(subcommand)]
    Update(UpdateCommands),

    /// Delete a resource
    #[command(subcommand)]
    Delete(DeleteCommands),

    /// Deploy the app
    Deploy(DeployArgs),

    /// Inspect current deployment status
    Inspect(InspectArgs),

    /// Rollback to a previous deployment
    Rollback(RollbackArgs),

    /// Show API keys for an app
    #[command(name = "api-keys")]
    ApiKeys(ApiKeysArgs),
}

// ============================================================================
// Subcommand argument structs
// ============================================================================

#[derive(Args, Debug)]
pub struct LoginArgs {
    /// Skip opening the browser and print the auth URL instead
    #[arg(long)]
    pub no_browser: bool,
}

#[derive(Args, Debug)]
pub struct LinkArgs {
    /// App name in org/app format
    pub app: String,
}

#[derive(Args, Debug)]
pub struct DeploymentsArgs {
    /// App name in org/app format (uses linked app if not specified)
    #[arg(long)]
    pub app: Option<String>,

    /// Maximum number of deployments to show
    #[arg(long, default_value = "10")]
    pub limit: usize,

    /// Filter by deployment status
    #[arg(long)]
    pub status: Option<String>,
}

#[derive(Args, Debug)]
pub struct ImagesArgs {
    /// Filter by channel (stable, beta, etc.)
    #[arg(long)]
    pub channel: Option<String>,
}

#[derive(Args, Debug)]
pub struct LogsArgs {
    /// App name in org/app format (uses linked app if not specified)
    #[arg(long)]
    pub app: Option<String>,

    /// Deployment ID (uses latest if not specified)
    #[arg(long)]
    pub deployment: Option<i64>,

    /// Maximum number of log entries to show
    #[arg(long, default_value = "100")]
    pub limit: usize,

    /// Follow logs in real-time
    #[arg(short, long)]
    pub follow: bool,
}

#[derive(Args, Debug)]
pub struct DeployArgs {
    /// App name in org/app format (uses linked app if not specified)
    #[arg(long)]
    pub app: Option<String>,

    /// Container image tag to deploy
    #[arg(long)]
    pub image: Option<String>,

    /// Number of replicas
    #[arg(long)]
    pub replicas: Option<i32>,

    /// Enable debug mode
    #[arg(long)]
    pub debug: bool,
}

#[derive(Args, Debug)]
pub struct InspectArgs {
    /// App name in org/app format (uses linked app if not specified)
    #[arg(long)]
    pub app: Option<String>,
}

#[derive(Args, Debug)]
pub struct RollbackArgs {
    /// App name in org/app format (uses linked app if not specified)
    #[arg(long)]
    pub app: Option<String>,

    /// Target deployment ID to rollback to
    #[arg(long)]
    pub target: Option<i64>,
}

#[derive(Args, Debug)]
pub struct ApiKeysArgs {
    /// App name in org/app format (uses linked app if not specified)
    #[arg(long)]
    pub app: Option<String>,

    /// Regenerate API key (1 or 2)
    #[arg(long)]
    pub regenerate: Option<u8>,
}

// ============================================================================
// Secrets subcommands
// ============================================================================

#[derive(Subcommand, Debug)]
pub enum SecretsCommands {
    /// List all secrets
    List(SecretsListArgs),

    /// Set a secret
    Set(SecretsSetArgs),

    /// Get a secret value
    Get(SecretsGetArgs),

    /// Delete a secret
    #[command(alias = "rm")]
    Delete(SecretsDeleteArgs),
}

#[derive(Args, Debug)]
pub struct SecretsListArgs {
    /// App name in org/app format (uses linked app if not specified)
    #[arg(long)]
    pub app: Option<String>,
}

#[derive(Args, Debug)]
