async fn execute_metrics(args: &MetricsArgs) -> Result<()> {
    let client = CloudClient::new()?;
    let app_name = require_app(args.app.as_deref())?;

    let response = client.get_app_metrics(&app_name).await?;

    if response.metrics.is_empty() {
        println!("No metrics available for {app_name}");
        return Ok(());
    }

    let mut table = TableOutput::new(vec![
        "POD",
        "CPU %",
        "MEMORY",
        "DISK USED",
        "DISK AVAILABLE",
        "DISK CAPACITY",
    ]);
    for (pod_name, metrics) in &response.metrics {
        table.add_row(vec![
            pod_name.clone(),
            format!("{:.1}", metrics.cpu_usage_percent),
            format_bytes(metrics.memory_usage_bytes),
            format_bytes(metrics.filesystem_usage_bytes),
            format_bytes(metrics.filesystem_available_bytes),
            format_bytes(metrics.filesystem_capacity_bytes),
        ]);
    }
    table.print();

    Ok(())
}

fn format_bytes(bytes: u64) -> String {
    const KIB: u64 = 1024;
    const MIB: u64 = KIB * 1024;
    const GIB: u64 = MIB * 1024;

    if bytes >= GIB {
        format!("{:.1} GiB", bytes as f64 / GIB as f64)
    } else if bytes >= MIB {
        format!("{:.1} MiB", bytes as f64 / MIB as f64)
    } else if bytes >= KIB {
        format!("{:.1} KiB", bytes as f64 / KIB as f64)
    } else {
        format!("{bytes} B")
    }
}

