 86→            self.channel.as_deref(),
 87→        )
 88→        .await
 89→        .map_err(|e| format!("Setup failed: {e}"))?;
 90→
 91→        let response = SetupResponse {
 92→            driver: AdbcDriver::Flightsql,
 93→            db_kwargs: HashMap::from([
 94→                (
 95→                    "uri".to_string(),
 96→                    serde_json::Value::String(state.flight_url.clone()),
 97→                ),
 98→                (
 99→                    "username".to_string(),
100→                    serde_json::Value::String(String::new()),
101→                ),
102→                (
103→                    "password".to_string(),
104→                    serde_json::Value::String(state.api_key.clone()),
105→                ),
106→            ]),
107→        };
108→
109→        self.runs.insert(run_id, state);
110→        Ok(response)
111→    }
112→    async fn metrics(&mut self, run_id: Uuid) -> std::result::Result<MetricsResponse, String> {
113→        // TODO: use cloud client to .get_app_metrics.
114→        // Note: ResourceMetrics cares about resource usage (e.g. `disk_write_bytes`) since last scrape.
115→        let _ = run_id;
116→        Ok(MetricsResponse {
117→            resource: ResourceMetrics {
118→                cpu_usage_percent: todo!(),
119→                memory_usage_bytes: todo!(),
120→                disk_read_bytes: todo!(),
121→                disk_write_bytes: todo!(),
122→                disk_read_iops: todo!(),
123→                disk_write_iops: todo!(),
124→            },
125→            ingestion: IngestionMetrics::default(),
126→        }())
127→    }
128→
129→    async fn create_tables(
130→        &mut self,
131→        run_id: Uuid,
132→        datasets: HashMap<String, DatasetConfig>,
133→    ) -> Result<CreateTablesResponse, String> {
134→        eprintln!("[stdio] create_tables: run_id={run_id}");
135→
136→        let state = self
137→            .runs
138→            .get_mut(&run_id)
139→            .ok_or_else(|| format!("Unknown run_id: {run_id}"))?;
140→
141→        let client = reqwest::Client::builder()
142→            .timeout(Duration::from_secs(60))
143→            .build()
144→            .map_err(|e| format!("Failed to create HTTP client: {e}"))?;
145→
146→        let sql_url = sql_url_from_cname(&state.cname);
147→
148→        for (table_name, config) in &datasets {
149→            let ddl = create_table_ddl(table_name, config);
150→            eprintln!("[stdio] create_tables: executing DDL: {ddl}");
151→
152→            let response = client
153→                .post(&sql_url)
154→                .header("X-API-Key", &state.api_key)
155→                .body(ddl.clone())
156→                .send()
157→                .await
158→                .map_err(|e| format!("Failed to send DDL for table '{table_name}': {e}"))?;
159→
160→            if !response.status().is_success() {
161→                let status = response.status();
162→                let body = response
163→                    .text()
164→                    .await
165→                    .unwrap_or_else(|_| "<failed to read body>".to_string());
166→                return Err(format!(
167→                    "DDL for table '{table_name}' failed ({status}): {body}"
168→                ));
169→            }
170→
171→            state.created_tables.push(table_name.clone());
172→            eprintln!("[stdio] create_tables: table '{table_name}' created");
173→        }
174→
175→        Ok(CreateTablesResponse { ok: true })
176→    }
177→
178→    async fn teardown(&mut self, run_id: Uuid) -> Result<TeardownResponse, String> {
179→        eprintln!("[stdio] teardown: run_id={run_id}");
180→
181→        let Some(state) = self.runs.remove(&run_id) else {
182→            eprintln!("[stdio] teardown: run_id={run_id} not found (already torn down?)");
183→            return Ok(TeardownResponse { ok: true });
184→        };
185→
186→        // Drop tables via DDL before deleting the app
187→        if !state.created_tables.is_empty() {
188→            let client = reqwest::Client::builder()
189→                .timeout(Duration::from_secs(30))
190→                .build()
191→                .map_err(|e| format!("Failed to create HTTP client: {e}"))?;
192→
193→            let sql_url = sql_url_from_cname(&state.cname);
194→
195→            for table_name in &state.created_tables {
196→                let ddl = format!("DROP TABLE IF EXISTS \"{table_name}\"");
197→                eprintln!("[stdio] teardown: executing DDL: {ddl}");
198→
199→                match client
200→                    .post(&sql_url)
201→                    .header("X-API-Key", &state.api_key)
202→                    .body(ddl)
203→                    .send()
204→                    .await
205→                {
206→                    Ok(response) if response.status().is_success() => {
207→                        eprintln!("[stdio] teardown: table '{table_name}' dropped");
208→                    }
209→                    Ok(response) => {
210→                        let status = response.status();
211→                        let body = response
212→                            .text()
213→                            .await
214→                            .unwrap_or_else(|_| "<failed to read body>".to_string());
215→                        eprintln!(
216→                            "[stdio] teardown: failed to drop table '{table_name}' ({status}): {body}"
217→                        );
218→                    }
219→                    Err(e) => {
220→                        eprintln!("[stdio] teardown: failed to drop table '{table_name}': {e}");
221→                    }
222→                }
223→            }
224→        }
225→
226→        eprintln!(
227→            "[stdio] teardown: deleting app {} at {}",
228→            state.app_id,
229→            state.cloud.base_url()
230→        );
231→
232→        commands::delete_app(&state.cloud, state.app_id)
233→            .await
234→            .map_err(|e| format!("Failed to delete app {}: {e}", state.app_id))?;
235→
236→        eprintln!("[stdio] teardown: app {} deleted", state.app_id);
237→        Ok(TeardownResponse { ok: true })
238→    }
239→}
