250→// ── Spice Cloud provisioning ─────────────────────────────────────────
251→
252→/// Provision a Spice Cloud app from the setup request.
253→///
254→/// Follows the same flow as `SpiceCloudSpicedStarter::start()`:
255→/// 1. Resolve the default cname / region
256→/// 2. Create or find the SCP app
257→/// 3. Generate and upload the spicepod from the dataset configs
258→/// 4. Set secrets (RUNNER + any env-based secrets)
259→/// 5. Create a deployment
260→/// 6. Wait for the deployment to become ready
261→async fn provision_spice_cloud_app(
262→    run_id: Uuid,
263→    api_url_override: Option<&str>,
264→    ready_wait: u64,
265→    channel: Option<&str>,
266→) -> anyhow::Result<RunState> {
267→    let cloud = commands::build_cloud_client(api_url_override)?;
268→
269→    let cname = commands::resolve_default_cname(&cloud).await?;
270→    let flight_url = commands::flight_url_from_cname(&cname);
271→    let run_id_str = run_id.to_string();
272→    let short_id = run_id_str.split('-').next().unwrap_or_default();
273→    let app_name = commands::sanitize_app_name(&format!("spidapter-{short_id}"));
274→
275→    eprintln!("[stdio] Spice Cloud API: {}", cloud.base_url());
276→    eprintln!("[stdio] Region cname: {cname}");
277→    eprintln!("[stdio] Flight endpoint: {flight_url}");
278→    eprintln!("[stdio] App name: {app_name}");
279→
280→    let (app_id, app_api_key) = commands::ensure_spice_cloud_app(&cloud, &app_name).await?;
281→
282→    let api_key = app_api_key.ok_or_else(|| {
283→        anyhow::anyhow!("Spice Cloud did not return an API key for app '{app_name}'")
284→    })?;
285→
286→    eprintln!("[stdio] App ID: {app_id}");
287→
288→    // Generate initial spicepod YAML (tables created later via create_tables)
289→    let spicepod_yaml = generate_initial_spicepod(&run_id);
290→    eprintln!("[stdio] Generated spicepod:\n{spicepod_yaml}");
291→
292→    eprintln!("[stdio] Uploading spicepod to app...");
293→    commands::apply_spicepod_to_app(&cloud, app_id, &spicepod_yaml).await?;
294→    eprintln!("[stdio] Spicepod uploaded");
295→
296→    // Set secrets from environment for any secret references in the spicepod
297→    eprintln!("[stdio] Setting secrets from spicepod...");
298→    commands::secrets::set_spicepod_secrets(&cloud, app_id, &spicepod_yaml).await?;
299→    eprintln!("[stdio] Spicepod secrets set");
300→
301→    eprintln!("[stdio] Setting RUNNER secret...");
302→    commands::secrets::set_secret(&cloud, app_id, "RUNNER", "spidapter").await?;
303→    eprintln!("[stdio] RUNNER secret set");
304→
305→    eprintln!("[stdio] Creating deployment...");
306→    commands::create_deployment(&cloud, app_id, channel).await?;
307→
308→    let poll_client = reqwest::Client::builder()
309→        .timeout(Duration::from_secs(600))
310→        .build()?;
311→    commands::wait_for_deployment_ready(
312→        &poll_client,
313→        &cname,
314→        &api_key,
315→        Duration::from_secs(ready_wait),
316→    )
317→    .await?;
318→
319→    eprintln!("[stdio] Spice Cloud deployment ready for app '{app_name}' at {flight_url}");
320→
321→    Ok(RunState {
322→        app_id,
323→        api_key,
324→        flight_url,
325→        cloud,
326→        cname,
327→        created_tables: Vec::new(),
328→    })
329→}
