336→/// Generate a `CREATE TABLE IF NOT EXISTS` DDL statement from a dataset's Arrow schema.
337→fn create_table_ddl(table_name: &str, config: &DatasetConfig) -> String {
338→    let columns: Vec<String> = config
339→        .schema
340→        .fields()
341→        .iter()
342→        .map(|f| {
343→            let sql_type = sql_type_for_arrow(f.data_type());
344→            let nullable = if f.is_nullable() { "" } else { " NOT NULL" };
345→            format!("\"{}\" {sql_type}{nullable}", f.name())
346→        })
347→        .collect();
348→
349→    format!(
350→        "CREATE TABLE IF NOT EXISTS \"{table_name}\" ({})",
351→        columns.join(", ")
352→    )
353→}
354→
355→/// Map Arrow data types to SQL type names for DDL.
356→fn sql_type_for_arrow(data_type: &DataType) -> &'static str {
357→    match data_type {
358→        DataType::Boolean => "BOOLEAN",
359→        DataType::Int8 => "TINYINT",
360→        DataType::Int16 => "SMALLINT",
361→        DataType::Int32 => "INT",
362→        DataType::Int64 => "BIGINT",
363→        DataType::UInt8 => "TINYINT",
364→        DataType::UInt16 => "SMALLINT",
365→        DataType::UInt32 => "INT",
366→        DataType::UInt64 => "BIGINT",
367→        DataType::Float32 => "FLOAT",
368→        DataType::Float64 => "DOUBLE",
369→        DataType::Utf8 | DataType::LargeUtf8 => "VARCHAR",
370→        DataType::Date32 | DataType::Date64 => "DATE",
371→        DataType::Timestamp(TimeUnit::Second, _) => "TIMESTAMP",
372→        DataType::Timestamp(TimeUnit::Millisecond, _) => "TIMESTAMP",
373→        DataType::Timestamp(TimeUnit::Microsecond, _) => "TIMESTAMP",
374→        DataType::Timestamp(TimeUnit::Nanosecond, _) => "TIMESTAMP",
375→        DataType::Decimal128(p, s) => {
376→            // Leak a formatted string for the static lifetime — only called at table creation
377→            // time with a small number of distinct precision/scale pairs.
378→            let formatted = format!("DECIMAL({p}, {s})");
379→            Box::leak(formatted.into_boxed_str())
380→        }
381→        DataType::Binary | DataType::LargeBinary => "BINARY",
382→        _ => "VARCHAR", // fallback
383→    }
384→}
385→
386→/// Generate the initial spicepod YAML with an Iceberg Glue catalog as the default catalog.
387→fn generate_initial_spicepod(run_id: &Uuid) -> String {
388→    let run_id_str = run_id.to_string();
389→    let short_id = run_id_str.split('-').next().unwrap_or_default();
390→    format!(
391→        r#"version: v1beta1
392→kind: Spicepod
393→name: spidapter-{short_id}
394→
395→catalogs:
396→  - from: iceberg:https://glue.us-east-1.amazonaws.com/iceberg/v1/catalogs/211125479522
397→    name: spice
398→    access: read_write_create
399→    params:
400→      iceberg_sigv4_enabled: true
401→      iceberg_s3_access_key_id: ${{secrets:AWS_ACCESS_KEY_ID}}
402→      iceberg_s3_secret_access_key: ${{secrets:AWS_SECRET_ACCESS_KEY}}
403→      iceberg_s3_region: us-east-1
404→"#
405→    )
406→}
