 38→    std::env::var("SPICEAI_API_KEY")
 39→        .or_else(|_| std::env::var("SPICE_API_KEY"))
 40→        .or_else(|_| std::env::var("SPICE_SPICEAI_API_KEY"))
 41→        .or_else(|_| std::env::var("SPICE_SPICEAI_TOKEN"))
 42→        .map_err(|_| {
