 58→pub(crate) async fn ensure_spice_cloud_app(
 59→    cloud: &CloudClient,
 60→    app_name: &str,
 61→) -> anyhow::Result<(i64, Option<String>)> {
 62→    let apps = cloud.list_apps().await?;
 63→    if let Some(app) = apps.into_iter().find(|a| a.name == app_name) {
 64→        return Ok((app.id, app.api_key));
 65→    }
 66→
 67→    let cname = resolve_default_cname(cloud).await?;
 68→
 69→    let create_result = cloud
 70→        .create_app(&CreateAppRequest {
 71→            name: app_name.to_string(),
 72→            description: None,
 73→            visibility: "private".to_string(),
 74→            cname: Some(cname),
 75→            tags: Some(BTreeMap::from([(
 76→                "kind".to_string(),
 77→                "cluster".to_string(),
 78→            )])),
 79→        })
 80→        .await;
 81→
 82→    match create_result {
 83→        Ok(app) => Ok((app.id, app.api_key)),
 84→        Err(spice_cloud_client::error::Error::Conflict { .. }) => {
 85→            // Race condition — another caller created it; re-fetch
 86→            let apps = cloud.list_apps().await?;
 87→            if let Some(app) = apps.into_iter().find(|a| a.name == app_name) {
 88→                return Ok((app.id, app.api_key));
 89→            }
 90→            Err(anyhow::anyhow!(
 91→                "App '{app_name}' not found after conflict on create"
 92→            ))
 93→        }
 94→        Err(e) => Err(anyhow::anyhow!(
 95→            "Failed to create Spice Cloud app '{app_name}': {e}"
 96→        )),
 97→    }
 98→}
