100→pub(crate) async fn resolve_default_cname(cloud: &CloudClient) -> anyhow::Result<String> {
101→    let regions = cloud.list_regions(None).await?;
102→
103→    // Find the region matching the `default` field, then return its cname
104→    if let Some(default_region) = &regions.default
105→        && !default_region.is_empty()
106→    {
107→        if let Some(region) = regions.regions.iter().find(|r| r.region == *default_region)
108→            && let Some(cname) = &region.cname
109→        {
110→            return Ok(cname.clone());
111→        }
112→        // Fall back to the default value itself if no matching region found
113→        return Ok(default_region.clone());
114→    }
115→
116→    if let Some(region) = regions
117→        .regions
118→        .iter()
119→        .find(|region| region.is_default && !region.disabled)
120→    {
121→        return Ok(region
122→            .cname
123→            .clone()
124→            .unwrap_or_else(|| region.region.clone()));
125→    }
126→
127→    if let Some(region) = regions.regions.iter().find(|region| !region.disabled) {
128→        return Ok(region
129→            .cname
130→            .clone()
131→            .unwrap_or_else(|| region.region.clone()));
132→    }
133→
134→    Err(anyhow::anyhow!(
135→        "Unable to determine a default Spice Cloud region (cname) for app creation"
136→    ))
137→}
