190→/// Wait for a Spice Cloud deployment to become ready by polling the SQL endpoint.
191→///
192→/// Sends `SELECT 1` to `https://{cname}.spiceai.io/v1/sql` until it returns a successful response.
193→pub(crate) async fn wait_for_deployment_ready(
194→    client: &Client,
195→    cname: &str,
196→    api_key: &str,
197→    timeout: Duration,
198→) -> anyhow::Result<()> {
199→    let sql_url = format!("https://{cname}.spiceai.io/v1/sql");
200→    eprintln!("Waiting for deployment to become ready at {sql_url}...");
201→
202→    let started = tokio::time::Instant::now();
203→    loop {
204→        if started.elapsed() > timeout {
205→            return Err(anyhow::anyhow!(
206→                "Timed out after {}s waiting for deployment to become ready at {sql_url}",
207→                timeout.as_secs(),
208→            ));
209→        }
210→
211→        let elapsed = started.elapsed().as_secs();
212→
213→        match client
214→            .post(&sql_url)
215→            .header("X-API-Key", api_key)
216→            .body("SELECT 1")
217→            .send()
218→            .await
219→        {
220→            Ok(response) if response.status().is_success() => {
221→                eprintln!("  Deployment ready ({elapsed}s elapsed)");
222→                return Ok(());
223→            }
224→            Ok(response) => {
225→                eprintln!("  Not ready: {} ({elapsed}s elapsed)", response.status());
226→            }
227→            Err(e) => {
228→                eprintln!("  Not ready: {e} ({elapsed}s elapsed)");
229→            }
230→        }
231→
232→        tokio::time::sleep(Duration::from_secs(5)).await;
233→    }
234→}
