236→/// Derive the Flight endpoint URL from a Spice Cloud cname.
237→///
238→/// Replaces the `-data` suffix with `-flight` and constructs `https://{flight_cname}.spiceai.io`.
239→/// For example, `us-east-1-dev-aws-data` becomes `https://us-east-1-dev-aws-flight.spiceai.io`.
240→pub(crate) fn flight_url_from_cname(cname: &str) -> String {
241→    let flight_cname = if let Some(prefix) = cname.strip_suffix("-data") {
242→        format!("{prefix}-flight")
243→    } else {
244→        cname.to_string()
245→    };
246→    format!("https://{flight_cname}.spiceai.io")
247→}
248→
249→/// Sanitize a spicepod name for use as a Spice Cloud app name.
250→///
251→/// App names can only contain letters, numbers, and hyphens.
252→/// Truncated to 42 characters to leave room for Kubernetes name prefixes
253→/// and suffixes (e.g. `spicepod-{name}-scheduler-0` must be ≤63 chars).
254→pub(crate) fn sanitize_app_name(name: &str) -> String {
255→    let sanitized: String = name
256→        .chars()
257→        .map(|c| {
258→            if c.is_ascii_alphanumeric() || c == '-' {
259→                c
260→            } else {
261→                '-'
262→            }
263→        })
264→        .take(42)
265→        .collect();
266→    sanitized.trim_end_matches('-').to_string()
267→}
