async fn metrics(&mut self, run_id: Uuid) -> std::result::Result<MetricsResponse, String> {
    let state = self
        .runs
        .get(&run_id)
        .ok_or_else(|| format!("No active run found for {run_id}"))?;

    let cloud_metrics = state
        .cloud
        .get_app_metrics(state.app_id)
        .await
        .map_err(|e| format!("Failed to fetch metrics: {e}"))?;

    let pods = cloud_metrics.metrics.values().collect::<Vec<_>>();

    let resource = if pods.is_empty() {
        ResourceMetrics::default()
    } else {
        let count = pods.len() as f64;
        let avg_cpu = pods.iter().map(|p| p.cpu_usage_percent).sum::<f64>() / count;
        let total_memory = pods.iter().map(|p| p.memory_usage_bytes).sum::<u64>();
        let total_fs_usage = pods.iter().map(|p| p.filesystem_usage_bytes).sum::<u64>();

        ResourceMetrics {
            cpu_usage_percent: Some(avg_cpu),
            memory_usage_bytes: Some(total_memory),
            disk_read_bytes: None,
            disk_write_bytes: Some(total_fs_usage),
            disk_read_iops: None,
            disk_write_iops: None,
        }
    };

    Ok(MetricsResponse {
        resource,
        ingestion: IngestionMetrics::default(),
    })
}

